import { TypeSafeClient } from "@typesafe-ai/sdk";
import { appendFileSync, closeSync, fsyncSync, openSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { applyAction, decideAction, getPlacement } from "../agent/jev-agent";
import type { Boundary } from "../agent/jev-agent";
import {
  advanceRound,
  checkWinCondition,
  cleanupAfterUnitActs,
  createGame,
  createUnit,
  getNextUnit,
  placeUnit,
  startPlay,
  unitActed,
} from "../engine/game";
import { clearTrainingListener, setTrainingListener } from "../training/emitter";
import { BALANCE } from "../types";
import type { BalanceConfig, GameConfig, UnitAction } from "../types";
import { atomicJSON, hash, LIMITS, WHITELIST } from "./core";
import type { Failure, Result } from "./core";

export const CREDENTIAL_FILE = "/Users/emma/.hermes/cache/scratch/sibyl-jev.env";
export function credential(text: string): string {
  const lines = text.split(/\r?\n/).filter((l) => /^\s*(?:export\s+)?TYPESAFE_API_KEY\s*=/.test(l));
  if (lines.length !== 1) throw Error("Credential file must contain exactly one TYPESAFE_API_KEY");
  let key = lines[0]!.replace(/^\s*(?:export\s+)?TYPESAFE_API_KEY\s*=\s*/, "").trim();
  if ((key.startsWith('"') && key.endsWith('"')) || (key.startsWith("'") && key.endsWith("'")))
    key = key.slice(1, -1);
  if (!key || /[\s`$\\"']/.test(key)) throw Error("Invalid credential file value");
  return key;
}
export interface MatchRequest {
  config: GameConfig;
  balance: BalanceConfig;
  codeCommit: string;
  cycleHash: string;
  attempt: number;
}
export function applyBalance(value: BalanceConfig) {
  const expected = structuredClone(BALANCE);
  for (const [path, bounds] of Object.entries(WHITELIST)) {
    const [, cls, stat] = path.split(".");
    const n = (value.unitStats as any)?.[cls!]?.[stat!];
    if (!Number.isInteger(n) || n < bounds.min || n > bounds.max)
      throw Error("Invalid numeric balance override");
    (expected.unitStats as any)[cls!][stat!] = n;
  }
  if (hash(expected) !== hash(value)) throw Error("Non-whitelisted balance override");
  // Preserve UNIT_STATS alias held by engine imports.
  for (const cls of Object.keys(BALANCE.unitStats))
    Object.assign((BALANCE.unitStats as any)[cls], (value.unitStats as any)[cls]);
}
export function failureKind(error: unknown): Failure {
  const e = error as {
    status?: number;
    statusCode?: number;
    response?: { status?: number };
    message?: string;
  };
  if (e?.status === 502 || e?.statusCode === 502 || e?.response?.status === 502) return "http_502";
  return "provider_error";
}
/** No production simulator fallback: test injection is only at the provider boundary. */
function describe(action: UnitAction): string {
  switch (action.type) {
    case "move":
      return `move → (${action.target.x},${action.target.y})`;
    case "ability":
      return `${action.ability}${action.target ? ` → (${action.target.x},${action.target.y})` : ""}${action.direction ? ` facing ${action.direction}` : ""}`;
    case "wait":
      return "wait";
    default:
      return "?";
  }
}
export async function playMatch(
  request: MatchRequest,
  provider: Boundary,
  record: (event: unknown) => void,
): Promise<Result> {
  applyBalance(request.balance);
  const state = createGame();
  let decisions = 0,
    failedDecisions = 0;
  let failure: Failure | null = null;
  const client: Boundary = {
    systemOne: (async (...args: Parameters<Boundary["systemOne"]>) => {
      if (decisions >= LIMITS.decisions) {
        failure = "decision_cap";
        throw Error("Decision cap");
      }
      const id = ++decisions;
      record({
        type: "provider_start",
        id,
        round: state.round,
        unit: state.activeUnit,
        request: args[0],
      });
      try {
        const response = await provider.systemOne(...args);
        record({ type: "provider_response", id, response });
        return response;
      } catch (error) {
        failure = failureKind(error);
        failedDecisions++;
        // Do not serialize exceptions: SDK errors may include request headers.
        record({ type: "provider_failure", id, failure });
        throw Error("Provider decision failed");
      }
    }) as Boundary["systemOne"],
  };
  setTrainingListener((event) => record({ type: "engine_event", event }));
  try {
    record({ type: "game_config", ...request });
    for (const side of ["player", "opponent"] as const) {
      const squad = request.config[side];
      const placement = await getPlacement(squad.units, side, squad.placementPrompt, client);
      for (const pick of squad.units) {
        const p = placement.placements.find((p) => p.name === pick.name);
        if (!p) throw Error("Missing placement");
        const unit = createUnit(
          `${side}-${pick.name}`,
          pick.name,
          pick.class,
          side,
          p.position,
          pick.prompt,
        );
        const error = placeUnit(state, unit, p.position);
        if (error) throw Error("Rejected placement");
      }
    }
    startPlay(state);
    let lastRoundLog: string[] = [];
    while (state.phase === "play") {
      const roundLog: string[] = [];
      let unit = getNextUnit(state);
      while (unit) {
        const actions: string[] = [];
        // Same two-action sequencing as executeJevTurn/main, with each decision journaled.
        for (let actionIndex = 0; actionIndex < 2; actionIndex++) {
          const decision = await decideAction(state, unit, lastRoundLog, client);
          const error = applyAction(state, unit, decision.action);
          record({
            type: "resolved_action",
            unit: unit.id,
            actionIndex,
            action: decision.action,
            error,
          });
          if (error) throw Error("Rejected action");
          actions.push(describe(decision.action));
        }
        roundLog.push(`${unit.name}: ${actions.join(" → ")}`);
        cleanupAfterUnitActs(state, unit);
        unitActed(state);
        if (checkWinCondition(state)) break;
        unit = getNextUnit(state);
      }
      if ((state.phase as string) === "ended") break;
      lastRoundLog = roundLog;
      if (!advanceRound(state)) break;
    }
  } catch {
    if (!failure) {
      failure = "decision_error";
      failedDecisions++;
    }
    record({ type: "match_failure", failure, failedDecisions });
  } finally {
    clearTrainingListener();
  }
  const clean = failure === null && state.phase === "ended" && !!state.terminalReason;
  const result: Result = {
    clean,
    winner: clean ? (state.winner ?? "draw") : null,
    reason: state.terminalReason ?? null,
    rounds: state.round,
    decisions,
    failedDecisions,
    failure,
    codeCommit: request.codeCommit,
    requestHash: hash(request),
  };
  record({ type: "final_state", state, result });
  return result;
}

if (import.meta.main) {
  // Explicit worker entrypoint only. No dotenv import, environment fallback, or legacy recorder.
  delete process.env.TYPESAFE_API_KEY;
  const path = process.argv[2];
  if (!path) throw Error("Match request path required");
  const request = JSON.parse(readFileSync(path, "utf8")) as MatchRequest;
  const dir = resolve(path, "..");
  const fd = openSync(`${dir}/events.jsonl`, "ax", 0o600);
  const record = (value: unknown) => {
    appendFileSync(fd, `${JSON.stringify(value)}\n`);
    fsyncSync(fd);
  };
  try {
    applyBalance(request.balance);
    const apiKey = credential(readFileSync(CREDENTIAL_FILE, "utf8"));
    const result = await playMatch(
      request,
      new TypeSafeClient({
        apiKey,
        defaultModel: "jev-latest",
        baseURL: "https://api.typesafe.ai",
        logLevel: "off",
      }),
      record,
    );
    atomicJSON(`${dir}/result.json`, result);
  } catch {
    atomicJSON(`${dir}/result.json`, {
      clean: false,
      winner: null,
      reason: null,
      rounds: 0,
      decisions: 0,
      failedDecisions: 1,
      failure: "worker_error",
      codeCommit: request.codeCommit,
      requestHash: hash(request),
    } satisfies Result);
    process.exitCode = 1;
  } finally {
    closeSync(fd);
  }
}

rules.src/balance/runner.ts:
import { bounded, safeEnv } from "./process";
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { BALANCE } from "../types";
import type { BalanceConfig, GameConfig, UnitClass } from "../types";
import { generateRandomConfig } from "../training/squads";
import {
  atomicJSON,
  candidateBalance,
  classScore,
  CLASSES,
  counts,
  evaluate,
  guard,
  hash,
  isClean,
  parseResult,
  LIMITS,
  PROPOSAL_SCHEMA,
  settle,
  swapped,
  WHITELIST,
} from "./core";
import type { Attempt, Checkpoint, Proposal, Result } from "./core";
import type { MatchRequest } from "./match";

const ROOT = resolve(import.meta.dir, "../..");
const DEST = join(ROOT, "experiments/jev-balance-20261006");
const RAW = join(DEST, "raw");
const CHECKPOINT = join(RAW, "checkpoint.json");
let deadline = Infinity;
const SOURCE_FILES = [
  "src/engine/game.ts",
  "src/types/index.ts",
  "src/agent/jev-agent.ts",
  "src/training/squads.ts",
  "src/training/emitter.ts",
  "src/training/recorder.ts",
  "src/training/schema.ts",
  "src/training/config.ts",
  "src/balance/core.ts",
  "src/balance/match.ts",
  "src/balance/runner.ts",
  "src/balance/process.ts",
  "scripts/jev-designer-pty.py",
  "bun.lock",
  "package.json",
];
function read<T>(path: string): T {
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch {
    throw Error("Unreadable or invalid experiment JSON");
  }
}
function command(args: string[], cwd = ROOT): string {
  const p = Bun.spawnSync(args, {
    cwd,
    env: safeEnv(),
    stdout: "pipe",
    stderr: "pipe",
    timeout: Math.max(1, Math.min(120000, deadline - Date.now())),
  });
  if (p.exitCode !== 0) throw Error(`Command failed: ${args[0]} ${args[1] ?? ""}`);
  return p.stdout.toString().trim();
}
function sources() {
  return Object.fromEntries(
    SOURCE_FILES.map((path) => [path, readFileSync(join(ROOT, path), "utf8")]),
  );
}
export function compatibleSources(
  before: Record<string, string>,
  after: Record<string, string>,
  migration?: { fromSourceHash: string; toSourceHash: string },
) {
  if (hash(before) === hash(after)) return true;
  if (
    !migration ||
    migration.fromSourceHash !== hash(before) ||
    migration.toSourceHash !== hash(after)
  )
    return false;
  return (
    Object.keys(before).length === Object.keys(after).length &&
    Object.entries(before).every(
      ([path, text]) =>
        ["src/balance/core.ts", "src/balance/runner.ts"].includes(path) || after[path] === text,
    )
  );
}
function sourceCompatible(m: Manifest) {
  const path = join(DEST, "operational-resume.json");
  return compatibleSources(m.rules, sources(), existsSync(path) ? read(path) : undefined);
}
export interface Manifest {
  cycle: number;
  codeCommit: string;
  sourceHash: string;
  rules: Record<string, string>;
  balance: BalanceConfig;
  whitelist: typeof WHITELIST;
  discovery: GameConfig[];
  evaluation: Record<UnitClass, GameConfig[]>;
}
function freeze(cycle: number): Manifest {
  const rules = sources();
  const evaluation = Object.fromEntries(
    CLASSES.map((cls) => {
      const configs: GameConfig[] = [];
      for (let tries = 0; configs.length < 8 && tries < 10000; tries++) {
        const config = generateRandomConfig();
        if (classScore(config, "draw", cls) !== null) configs.push(config);
      }
      if (configs.length !== 8) throw Error("Unable to generate matched fixtures");
      return [cls, configs];
    }),
  ) as Record<UnitClass, GameConfig[]>;
  return {
    cycle,
    codeCommit: command(["git", "rev-parse", "HEAD"]),
    sourceHash: hash(rules),
    rules,
    balance: existsSync(join(DEST, "accepted-balance.json"))
      ? read(join(DEST, "accepted-balance.json"))
      : structuredClone(BALANCE),
    whitelist: WHITELIST,
    discovery: Array.from({ length: 25 }, () => generateRandomConfig()),
    evaluation,
  };
}
export function failure(request: MatchRequest, kind: Result["failure"]): Result {
  return {
    clean: false,
    winner: null,
    reason: null,
    rounds: 0,
    decisions: 0,
    failedDecisions: 1,
    failure: kind,
    codeCommit: request.codeCommit,
    requestHash: hash(request),
  };
}
export function journalFailure(
  request: MatchRequest,
  kind: Result["failure"],
  journal: string,
): Result {
  const result = failure(request, kind);
  let responses = 0,
    failed = 0,
    recordedFailures = 0;
  for (const line of journal.split("\n")) {
    let e: any;
    try {
      e = JSON.parse(line);
    } catch {
      continue;
    } // last append may be torn
    if (e.type === "provider_start") result.decisions++;
    if (e.type === "provider_response") responses++;
    if (e.type === "provider_failure") failed++;
    if (e.type === "match_failure") recordedFailures = e.failedDecisions;
    if (e.type === "engine_event" && e.event?.type === "game_end") {
      result.reason = e.event.reason;
      result.winner = e.event.winner;
      result.rounds = e.event.totalTurns;
    }
  }
  result.failedDecisions = Math.max(
    recordedFailures,
    failed + Math.max(0, result.decisions - responses - failed),
  );
  return result;
}
function recovered(request: MatchRequest, kind: Result["failure"], dir: string) {
  return existsSync(join(dir, "events.jsonl"))
    ? journalFailure(request, kind, readFileSync(join(dir, "events.jsonl"), "utf8"))
    : failure(request, kind);
}
export function evidence(s: Checkpoint, m: Manifest) {
  const games = s.attempts.filter(
    (a) => a.cycle === m.cycle && a.stage === "discovery" && a.result && isClean(a.result),
  );
  if (games.length !== 50 || new Set(games.map((a) => a.slot)).size !== 50)
    throw Error("Designer requires exactly 50 fresh CLEAN discovery games");
  const classes = Object.fromEntries(
    CLASSES.map((cls) => {
      const pairs: number[] = [];
      for (let pair = 0; pair < 25; pair++) {
        const scores = games
          .filter((a) => Math.floor(a.slot / 2) === pair)
          .map((a) =>
            classScore(
              a.slot % 2 ? swapped(m.discovery[pair]!) : m.discovery[pair]!,
              a.result!.winner,
              cls,
            ),
          );
        if (scores.length === 2 && scores.every((x) => x !== null))
          pairs.push((scores[0]! + scores[1]!) / 2);
      }
      return [
        cls,
        {
          informativePairs: pairs.length,
          meanScore: pairs.length ? pairs.reduce((a, b) => a + b, 0) / pairs.length : null,
          pairScores: pairs,
        },
      ];
    }),
  );
  return {
    cycle: m.cycle,
    manifestHash: hash(m),
    codeCommit: m.codeCommit,
    cleanDiscovery: 50,
    counts: counts({
      ...s,
      attempts: s.attempts.filter((a) => a.cycle < m.cycle || a.stage === "discovery"),
    }),
    classes,
    games: games.map((a) => ({ attempt: a.id, slot: a.slot, ...a.result })),
  };
}
async function runAttempt(
  s: Checkpoint,
  m: Manifest,
  stage: Attempt["stage"],
  slot: number,
  retry: number,
  config: GameConfig,
  balance: BalanceConfig,
) {
  guard(s);
  if (!sourceCompatible(m)) throw Error("Frozen source changed");
  const attempt: Attempt = { id: s.attempts.length + 1, cycle: m.cycle, stage, slot, retry };
  const dir = join(RAW, `attempt-${String(attempt.id).padStart(4, "0")}`);
  mkdirSync(dir, { recursive: true, mode: 0o700 });
  const request: MatchRequest = {
    config,
    balance,
    codeCommit: command(["git", "rev-parse", "HEAD"]),
    cycleHash: hash(m),
    attempt: attempt.id,
  };
  atomicJSON(join(dir, "request.json"), request);
  s.pending = attempt;
  s.attempts.push(attempt);
  atomicJSON(CHECKPOINT, s);
  const run = await bounded(
    [process.execPath, "run", join(ROOT, "src/balance/match.ts"), join(dir, "request.json")],
    join(dir, "worker.log"),
    Math.min(LIMITS.matchMs, s.startedAt + LIMITS.wallMs - Date.now()),
    ROOT,
  );
  let result = recovered(
    request,
    run.interrupted ? "interrupted" : run.timedOut ? "timeout" : "worker_error",
    dir,
  );
  if (!run.interrupted && !run.timedOut && existsSync(join(dir, "result.json"))) {
    const candidate = parseResult(read(join(dir, "result.json")));
    if (
      candidate &&
      candidate.requestHash === hash(request) &&
      candidate.codeCommit === request.codeCommit &&
      (run.code === 0 || !candidate.clean)
    )
      result = candidate;
  }
  settle(s, result);
  atomicJSON(CHECKPOINT, s);
}
async function slot(
