    [
      "python3",
      join(ROOT, "scripts/jev-designer-pty.py"),
      codex,
      privateDir,
      join(privateDir, "schema.json"),
      output,
      join(privateDir, "prompt.txt"),
      String(seconds),
    ],
    join(privateDir, "pty.log"),
    Math.min((seconds + 2) * 1000, deadline - Date.now()),
    ROOT,
  );
