      ? read<Checkpoint>(CHECKPOINT)
      : {
          version: 1,
          startedAt: Date.now(),
          cycle: 1,
          attempts: [],
          manifestHashes: {},
          consecutiveFailures: 0,
          pending: null,
          halted: null,
          complete: false,
